package com.theone.cinema.tv;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
public class PlaybackPriorityTest {
 @Test public void pauseCancelsActiveRequestsAndRejectsNewDownloads()throws Exception{PlaybackPriority priority=new PlaybackPriority();AtomicInteger cancelled=new AtomicInteger();PlaybackPriority.Ticket first=priority.register(cancelled::incrementAndGet);PlaybackPriority.Ticket completed=priority.register(cancelled::incrementAndGet);completed.close();for(Runnable cancel:priority.pause())cancel.run();assertEquals(1,cancelled.get());assertTrue(priority.isPaused());try{priority.register(cancelled::incrementAndGet);fail("Playback must own bandwidth");}catch(IOException expected){}assertTrue(priority.pause().isEmpty());first.close();}
 @Test public void pausedBufferedReaderCannotContinueConsumingCatalog()throws Exception{PlaybackPriority priority=new PlaybackPriority();InputStream stream=priority.checked(new ByteArrayInputStream(new byte[]{1,2,3}));assertEquals(1,stream.read());priority.pause();try{stream.read(new byte[2]);fail("Catalog reads must stop");}catch(IOException expected){}priority.resume();assertEquals(2,stream.read());priority.register(()->{}).close();}
 @Test public void interruptedDiskCacheAndGroupingStopImmediately()throws Exception{CatalogEntry entry=new CatalogEntry(1,"EN - Test","mp4","","","movies",0);ByteArrayOutputStream bytes=new ByteArrayOutputStream();CatalogCodec.write(bytes,Collections.singletonList(entry));Thread.currentThread().interrupt();try{try{CatalogEntry.group(Collections.singletonList(entry));fail();}catch(CancellationException expected){}try{CatalogCodec.read(new ByteArrayInputStream(bytes.toByteArray()),"movies");fail();}catch(InterruptedIOException expected){}}finally{Thread.interrupted();}}
 @Test public void hdDevicePrefers1080Then720Before4k(){List<CatalogEntry> entries=new ArrayList<>(Arrays.asList(new CatalogEntry(1,"EN - Film 4K","mp4","","","movies",9),new CatalogEntry(2,"EN - Film FHD","mp4","","","movies",5),new CatalogEntry(3,"EN - Film HD","mp4","","","movies",1)));entries.sort(CatalogEntry.playbackOrder("en",1080));assertEquals(2,entries.get(0).id);assertEquals(3,entries.get(1).id);assertEquals(1,entries.get(2).id);entries.sort(CatalogEntry.playbackOrder("en",2160));assertEquals(1,entries.get(0).id);}
 @Test public void selectedLanguageStillHasPriorityOverQuality(){List<CatalogEntry> entries=new ArrayList<>(Arrays.asList(new CatalogEntry(1,"EN - Film FHD","mp4","","","movies",0),new CatalogEntry(2,"NL - Film HD","mp4","","","movies",0)));entries.sort(CatalogEntry.playbackOrder("nl",1080));assertEquals("nl",entries.get(0).languageCode());}
}
